1	// Composition runtime for composed tick/1 solvers (research/composition-20261021/HARNESS.md §2). $0, no model calls.
2	//
3	// A composed program is a parent orchestrator plus sub-workflow modules, each declared in a manifest
4	// (composition.json) with a typed input and output, the effect kinds and human-task kinds it may emit, whether it may
5	// set timers, the systems it may read and the modules it may call. The runtime, not the builder, runs the program:
6	//   - the parent gets the host's case-tick (its own state instead of the carry) and reaches modules only through
7	//     ctx.call(module, key, input) (a typed call to the sub-workflow instance `key` of `module`) and ctx.deliver(event)
8	//     (an effect result, timer or human-task event the module instance caused, routed back to it by provenance);
9	//   - every module instance has its own durable state slot; the parent never sees it, only the module's typed output;
10	//   - every effect, timer and human task is attributed to the module (or the parent) that emitted it, and checked
11	//     against that emitter's declaration; calls are checked against the declared call graph; inputs and outputs
12	//     against the declared schemas; reads against the declared systems. A breach is an interface violation, recorded
13	//     per tick. Mode 'strict' (the default) also enforces: an undeclared effect, timer or task is dropped (never
14	//     reaches the platform) and an undeclared call, a schema breach or a recursion is refused (an error thrown to the
15	//     caller). Mode 'audit' records and lets everything through.
16	//   - the tick's output is an ordinary TickOutput; the per-tick trace rides in `decisions.composition` (E8 grades
17	//     `decisions.subject` only, contract §3.1), so the host, the oracle and every existing tool are unchanged, and the
18	//     harness re-verifies the trace against the trusted manifest from the journal (trace.mjs).
19	// This file imports nothing: bundle.mjs inlines it into the solver.mjs the sandbox runs (exports stripped).
20	
21	export const RUNTIME_VERSION = 'compose-runtime/1';
22	export const MODULE_ID = /^[a-z][a-z0-9-]{0,39}$/;
23	export const PORTABLE = Object.freeze(['type', 'properties', 'required', 'additionalProperties', 'items', 'enum', 'const',
24	  'minimum', 'maximum', 'minItems', 'maxItems', 'minLength', 'maxLength', 'description']);
25	const MAX_DEPTH = 6;
26	const MAX_ID = 200;
27	const isObj = v => v !== null && typeof v === 'object' && !Array.isArray(v);
28	const own = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
29	const jcopy = v => (v === undefined ? undefined : JSON.parse(JSON.stringify(v)));
30	
31	/** An interface violation thrown to the caller (strict mode) or an error the runtime raises itself. */
32	export class InterfaceError extends Error {
33	  constructor(code, message) { super(`${code}: ${message}`); this.name = 'InterfaceError'; this.code = code; }
34	}
35	
36	// ---------------------------------------------------------------------------------------------------------------------
37	// Portable-subset JSON Schema (the host's subset, beds/ebed/host/schema.mjs), self-contained.
38	
39	/** Problems of a schema under the portable subset ([] when fine). */
40	export function schemaProblems(schema, path = '#', depth = 0) {
41	  const out = [];
42	  if (depth > 20) return [`${path}: nested too deeply`];
43	  if (!isObj(schema)) return [`${path}: must be an object`];
44	  for (const k of Object.keys(schema)) if (!PORTABLE.includes(k)) out.push(`${path}: keyword ${k} is outside the portable subset`);
45	  if (own(schema, 'type')) {
46	    const ts = [].concat(schema.type);
47	    if (!ts.length || ts.some(t => !['object', 'array', 'string', 'number', 'integer', 'boolean', 'null'].includes(t))) out.push(`${path}: bad type`);
48	  }
49	  if (own(schema, 'properties')) {
50	    if (!isObj(schema.properties)) out.push(`${path}.properties: must be an object`);
51	    else for (const [k, s] of Object.entries(schema.properties)) out.push(...schemaProblems(s, `${path}.properties.${k}`, depth + 1));
52	  }
53	  if (own(schema, 'required') && !(Array.isArray(schema.required) && schema.required.every(x => typeof x === 'string'))) out.push(`${path}.required: must be strings`);
54	  if (own(schema, 'additionalProperties') && typeof schema.additionalProperties !== 'boolean') out.push(...schemaProblems(schema.additionalProperties, `${path}.additionalProperties`, depth + 1));
55	  if (own(schema, 'items')) out.push(...schemaProblems(schema.items, `${path}.items`, depth + 1));
56	  if (own(schema, 'enum') && !(Array.isArray(schema.enum) && schema.enum.length)) out.push(`${path}.enum: must be a non-empty array`);
57	  return out.slice(0, 20);
58	}
59	
60	const typeOk = (t, v) => (t === 'null' ? v === null : t === 'object' ? isObj(v) : t === 'array' ? Array.isArray(v)
61	  : t === 'string' ? typeof v === 'string' : t === 'number' ? typeof v === 'number' && Number.isFinite(v)
62	  : t === 'integer' ? Number.isInteger(v) : t === 'boolean' ? typeof v === 'boolean' : false);
63	const deepEq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
64	
65	/** Validation errors of `value` against a portable-subset schema ([] when valid; at most 8). */
66	export function validate(schema, value, path = '$') {
67	  const errs = [];
68	  const walk = (s, v, p) => {
69	    if (errs.length >= 8 || !isObj(s)) return;
70	    if (own(s, 'type') && ![].concat(s.type).some(t => typeOk(t, v))) { errs.push(`${p}: expected ${[].concat(s.type).join('|')}`); return; }
71	    if (own(s, 'enum') && !s.enum.some(x => deepEq(x, v))) errs.push(`${p}: not one of ${JSON.stringify(s.enum).slice(0, 80)}`);
72	    if (own(s, 'const') && !deepEq(s.const, v)) errs.push(`${p}: must be ${JSON.stringify(s.const).slice(0, 80)}`);
73	    if (typeof v === 'number') {
74	      if (own(s, 'minimum') && v < s.minimum) errs.push(`${p}: below ${s.minimum}`);
75	      if (own(s, 'maximum') && v > s.maximum) errs.push(`${p}: above ${s.maximum}`);
76	    }
77	    if (typeof v === 'string') {
78	      const n = [...v].length;
79	      if (own(s, 'minLength') && n < s.minLength) errs.push(`${p}: shorter than ${s.minLength}`);
80	      if (own(s, 'maxLength') && n > s.maxLength) errs.push(`${p}: longer than ${s.maxLength}`);
81	    }
82	    if (Array.isArray(v)) {
83	      if (own(s, 'minItems') && v.length < s.minItems) errs.push(`${p}: fewer than ${s.minItems} items`);
84	      if (own(s, 'maxItems') && v.length > s.maxItems) errs.push(`${p}: more than ${s.maxItems} items`);
85	      if (own(s, 'items')) v.forEach((x, i) => walk(s.items, x, `${p}[${i}]`));
86	    }
87	    if (isObj(v)) {
88	      for (const k of s.required ?? []) if (!own(v, k)) errs.push(`${p}.${k}: required`);
89	      const props = isObj(s.properties) ? s.properties : {};
90	      for (const [k, x] of Object.entries(v)) {
91	        if (own(props, k)) walk(props[k], x, `${p}.${k}`);
92	        else if (s.additionalProperties === false) errs.push(`${p}.${k}: not allowed`);
93	        else if (isObj(s.additionalProperties)) walk(s.additionalProperties, x, `${p}.${k}`);
94	      }
95	    }
96	  };
97	  walk(schema, value, path);
98	  return errs;
99	}
100	
101	// ---------------------------------------------------------------------------------------------------------------------
102	// Manifest
103	
104	/**
105	 * Problems of a composition manifest ([] when valid). `ops` (optional): the item's effect ops as 'system.op' names, to
106	 * check declared effect kinds; `taskKinds` (optional): the item's human-task kinds.
107	 */
108	export function manifestProblems(m, { ops = null, taskKinds = null } = {}) {
109	  const out = [];
110	  if (!isObj(m)) return ['manifest: must be an object'];
111	  if (m.version !== 1) out.push('version: must be 1');
112	  if (!isObj(m.parent)) out.push('parent: required object');
113	  if (!isObj(m.modules) || !Object.keys(m.modules).length) out.push('modules: required, at least one module');
114	  if (out.length) return out;
115	  const ids = Object.keys(m.modules);
116	  for (const id of ids) if (!MODULE_ID.test(id) || id === 'parent') out.push(`modules.${id}: id must match ${MODULE_ID} and not be "parent"`);
117	  const kindOk = k => typeof k === 'string' && (!ops || ops.includes(k.split(':')[0]));
118	  const checkDecl = (d, where, isParent) => {
119	    for (const k of Object.keys(d)) if (!['file', 'purpose', 'rules', 'input', 'output', 'effects', 'humanTasks', 'timers', 'calls', 'reads'].includes(k)) out.push(`${where}: unknown field ${k}`);
120	    if (typeof d.file !== 'string' || !/^[A-Za-z0-9_./-]+\.mjs$/.test(d.file) || d.file.includes('..')) out.push(`${where}.file: a relative .mjs path`);
121	    for (const f of ['effects', 'humanTasks', 'calls', 'reads', 'rules']) if (own(d, f) && !(Array.isArray(d[f]) && d[f].every(x => typeof x === 'string'))) out.push(`${where}.${f}: array of strings`);
122	    for (const k of d.effects ?? []) if (!kindOk(k)) out.push(`${where}.effects: unknown effect kind ${k}`);
123	    if (taskKinds) for (const k of d.humanTasks ?? []) if (!taskKinds.includes(k)) out.push(`${where}.humanTasks: unknown task kind ${k}`);
124	    for (const c of d.calls ?? []) if (!own(m.modules, c)) out.push(`${where}.calls: unknown module ${c}`);
125	    if (own(d, 'timers') && typeof d.timers !== 'boolean') out.push(`${where}.timers: boolean`);
126	    if (!isParent) {
127	      for (const f of ['input', 'output']) {
128	        if (!own(d, f)) out.push(`${where}.${f}: required schema`);
129	        else out.push(...schemaProblems(d[f], `${where}.${f}`));
130	      }
131	    }
132	  };
133	  checkDecl(m.parent, 'parent', true);
134	  for (const id of ids) checkDecl(m.modules[id], `modules.${id}`, false);
135	  const files = [m.parent.file, ...ids.map(id => m.modules[id].file)];
136	  if (new Set(files).size !== files.length) out.push('files: every module needs its own file');
137	  // The call graph must be acyclic (a sub-workflow never calls back up).
138	  const state = {};
139	  const visit = (id, trail) => {
140	    if (state[id] === 2) return;
141	    if (state[id] === 1) { out.push(`calls: cycle ${[...trail, id].join(' -> ')}`); return; }
142	    state[id] = 1;
143	    for (const c of m.modules[id]?.calls ?? []) if (own(m.modules, c)) visit(c, [...trail, id]);
144	    state[id] = 2;
145	  };
146	  for (const id of ids) visit(id, []);
147	  return out.slice(0, 40);
148	}
149	
150	/** Modules reachable from the parent through the declared call graph. */
151	export function reachable(m) {
152	  const seen = new Set();
153	  const go = id => { for (const c of (id === 'parent' ? m.parent.calls : m.modules[id]?.calls) ?? []) if (!seen.has(c)) { seen.add(c); go(c); } };
154	  go('parent');
155	  return seen;
156	}
157	
158	// ---------------------------------------------------------------------------------------------------------------------
159	// The runtime
160	
161	/** Default realm: trusted in-process modules (plain objects, JSON copies across the boundary). */
162	export function plainRealm() {
163	  return {
164	    toRealm: (who, v) => jcopy(v),
165	    makeCtx: (who, meta, h) => ({ ...meta, get files() { return h.files(); }, query: h.query, status: h.status, instances: h.instances,
166	      call: h.call, deliver: h.deliver, ownerOf: h.ownerOf, emit: h.emit }),
167	  };
168	}
169	
170	/**
171	 * createComposedSolver({ manifest, parent, modules, kindsOf, mode, realm, id }) → { id, tick(input, hostCtx) }.
172	 * parent: { tick(input, ctx) → { decisions, state?, effects?, obligations?, humanTasks?, merge?, close? } };
173	 * modules: { [id]: { step?(input, ctx) → Result, onEvent?(event, ctx) → Result } },
174	 *   Result = { output?, state?, effects?, obligations?: { upsert?, cancel? }, humanTasks? };
175	 * kindsOf(effect) → the effect's qualified kinds, least to most specific (e.g. ['notify.send', 'notify.send:order-cancelled']).
176	 */
177	export function createComposedSolver({ manifest, parent, modules, kindsOf = e => [`${e.system}.${e.op}`], mode = 'strict', realm = plainRealm(), id = 'composed' }) {
178	  if (!['strict', 'audit'].includes(mode)) throw new Error(`mode must be strict or audit: ${mode}`);
179	  const M = manifest;
180	  const reach = reachable(M);
181	  const declOf = who => (who === 'parent' ? M.parent : M.modules[who]);
182	
183	  function tick(input, hostCtx) {
184	    const carry = isObj(input.carry) && input.carry.cv === 1 ? jcopy(input.carry) : { cv: 1, p: null, m: {} };
185	    const out = { effects: [], owners: [], upsert: [], cancel: [], tasks: [] };
186	    const trace = { v: 1, owners: out.owners, calls: [], violations: [], dropped: [] };
187	    const undo = [];                              // undo log for atomic calls
188	    const stack = [];                             // the modules currently running (call chain)
189	    const violation = (code, who, detail, extra = {}) => { trace.violations.push({ code, module: who, ...(stack.length ? { by: stack.at(-1) } : {}), detail: String(detail).slice(0, 300), ...extra }); };
190	    const strict = mode === 'strict';
191	    const refuse = (code, who, detail) => { violation(code, who, detail); if (strict) throw new InterfaceError(code, detail); };
192	
193	    // --- names: every key, timer id and task id of a module instance lives in its own namespace
194	    //     `<module>/<instance key>/<local>`, so routing back to it is parsed from the name, never remembered (a crash
195	    //     that loses the carry loses no routing). The parent's names are its own, unprefixed, without '/'.
196	    const ns = (who, ikey, local) => {
197	      if (who === 'parent') return local;
198	      const s = `${who}/${ikey}/${local}`;
199	      if (s.length > MAX_ID) throw new InterfaceError('id-too-long', `${who}: ${s.slice(0, 80)}... is longer than ${MAX_ID} characters (shorten the instance key or the local name)`);
200	      return s;
201	    };
202	    const parse = name => {
203	      if (typeof name !== 'string') return null;
204	      const i = name.indexOf('/'), j = i < 0 ? -1 : name.indexOf('/', i + 1);
205	      if (i < 0 || j < 0) return null;
206	      const mid = name.slice(0, i);
207	      return own(M.modules, mid) ? { module: mid, key: name.slice(i + 1, j), local: name.slice(j + 1) } : null;
208	    };
209	    const emittedLocal = new Map();               // local key -> full key, for `after` across modules in one tick
210	
211	    // --- effect, timer and task intake, attributed to `who` ---
212	    function takeEffect(who, ikey, e0) {
213	      if (!isObj(e0) || typeof e0.system !== 'string' || typeof e0.op !== 'string') { violation('bad-effect', who, 'an effect must be { system, op, args, key? }'); return; }
214	      const e = jcopy(e0);
215	      const decl = declOf(who);
216	      const kinds = kindsOf(e);
217	      const declared = decl.effects ?? [];
218	      if (!kinds.some(k => declared.includes(k))) {
219	        violation(who === 'parent' ? 'parent-effect-undeclared' : 'effect-undeclared', who, `${kinds.at(-1) ?? '?'} is not among ${JSON.stringify(declared).slice(0, 200)}`, { kind: kinds.at(-1) ?? null });
220	        if (strict) { trace.dropped.push({ owner: who, kind: kinds.at(-1) ?? null, key: e.key ?? e.args?.items?.[0]?.key ?? null }); return; }
221	      }
222	      if (who === 'parent' && [e.key, ...(Array.isArray(e.args?.items) ? e.args.items.map(i => i?.key) : [])].some(x => typeof x === 'string' && x.includes('/'))) {
223	        violation('parent-key', who, 'parent keys may not contain "/" (reserved for module namespaces)');
224	        if (strict) return;
225	      }
226	      const locals = [];
227	      if (typeof e.key === 'string') { locals.push(e.key); e.key = ns(who, ikey, e.key); }
228	      if (Array.isArray(e.args?.items)) for (const it of e.args.items) if (isObj(it) && typeof it.key === 'string') { locals.push(it.key); it.key = ns(who, ikey, it.key); }
229	      for (const ref of ['after', 'compensates']) if (typeof e[ref] === 'string') {
230	        const mine = ns(who, ikey, e[ref]);
231	        e[ref] = out.effects.some(x => x.key === mine) ? mine : (emittedLocal.get(e[ref]) ?? mine);
232	      }
233	      out.effects.push(e); out.owners.push(who);
234	      const added = [];
235	      for (const l of locals) if (!emittedLocal.has(l)) { emittedLocal.set(l, ns(who, ikey, l)); added.push(l); }
236	      undo.push(() => { out.effects.pop(); out.owners.pop(); for (const l of added) emittedLocal.delete(l); });
237	    }
238	    function takeObligations(who, ikey, ob) {
239	      if (ob === undefined || ob === null) return;
240	      if (!isObj(ob)) { violation('bad-result', who, 'obligations must be { upsert, cancel }'); return; }
241	      const up = Array.isArray(ob.upsert) ? ob.upsert : [], cancel = Array.isArray(ob.cancel) ? ob.cancel : [];
242	      if (!up.length && !cancel.length) return;
243	      if (who !== 'parent' && declOf(who).timers !== true) { violation('timer-undeclared', who, 'timers: true is not declared'); if (strict) return; }
244	      for (const o of up) {
245	        if (!isObj(o) || typeof o.id !== 'string') { violation('bad-result', who, 'an obligation needs an id'); continue; }
246	        out.upsert.push({ ...o, id: ns(who, ikey, o.id) }); undo.push(() => out.upsert.pop());
247	      }
248	      for (const c of cancel) if (typeof c === 'string') { out.cancel.push(ns(who, ikey, c)); undo.push(() => out.cancel.pop()); }
249	    }
250	    function takeTasks(who, ikey, tasks) {
251	      if (tasks === undefined || tasks === null) return;
252	      if (!Array.isArray(tasks)) { violation('bad-result', who, 'humanTasks must be an array'); return; }
253	      for (const t of tasks) {
254	        if (!isObj(t) || typeof t.id !== 'string') { violation('bad-result', who, 'a human task needs an id'); continue; }
255	        if (!(declOf(who).humanTasks ?? []).includes(t.kind)) {
256	          violation(who === 'parent' ? 'parent-task-undeclared' : 'task-undeclared', who, `task kind ${t.kind} is not declared`, { kind: t.kind ?? null });
257	          if (strict) continue;
258	        }
259	        out.tasks.push({ ...t, id: ns(who, ikey, t.id) }); undo.push(() => out.tasks.pop());
260	      }
261	    }
262	
263	    // --- ownership of inbound events (provenance from the names, never business meaning) ---
264	    const nameOf = ev => {
265	      if (!isObj(ev) || !isObj(ev.payload)) return null;
266	      const p = ev.payload;
267	      if (ev.type === 'effect.result') return typeof p.key === 'string' ? p.key : Array.isArray(p.items) ? p.items.map(i => i?.key).find(x => typeof x === 'string') ?? null : null;
268	      if (ev.type === 'timer.fired') return p.obligationId ?? null;
269	      if (typeof ev.type === 'string' && ev.type.startsWith('humanTask.')) return p.taskId ?? null;
270	      return null;
271	    };
272	    function ownerOf(ev) { const o = parse(nameOf(ev)); return o ? { module: o.module, key: o.key } : null; }
273	    const localise = ev => {
274	      const e = jcopy(ev);
275	      const strip = n => parse(n)?.local ?? n;
276	      if (e.type === 'effect.result') {
277	        if (typeof e.payload.key === 'string') e.payload.key = strip(e.payload.key);
278	        if (Array.isArray(e.payload.items)) for (const it of e.payload.items) if (isObj(it) && typeof it.key === 'string') it.key = strip(it.key);
279	      }
280	      if (e.type === 'timer.fired') e.payload.obligationId = strip(e.payload.obligationId);
281	      if (typeof e.type === 'string' && e.type.startsWith('humanTask.')) e.payload.taskId = strip(e.payload.taskId);
282	      return e;
283	    };
284	
285	    // --- reads ---
286	    const readable = who => {
287	      if (who === 'parent') return null;                       // the parent reads everything (correlation is its job)
288	      const d = declOf(who);
289	      return new Set([...(d.reads ?? []), ...(d.effects ?? []).map(k => k.split('.')[0])]);
290	    };
291	    const handlersFor = (who, ikey) => {
292	      const can = readable(who);
293	      const checkRead = system => { if (can && !can.has(system)) refuse('read-undeclared', who, `reads of ${system} are not declared`); };
294	      return {
295	        files: () => realm.toRealm(who, hostCtx.files),
296	        query: (table, filter) => { checkRead(String(table).split('.')[0]); return realm.toRealm(who, hostCtx.query(table, filter)); },
297	        status: (system, key) => { checkRead(system); return hostCtx.status(system, who === 'parent' ? key : ns(who, ikey, String(key))); },
298	        instances: f => { if (who !== 'parent') refuse('instances-module', who, 'only the parent reads the open-instance index'); return realm.toRealm(who, hostCtx.instances(f)); },
299	        call: (mid, key, inp) => realm.toRealm(who, invoke(who, mid, key, 'call', inp)),
300	        deliver: ev => {
301	          const o = ownerOf(ev);
302	          if (!o) throw new InterfaceError('deliver-unowned', `no module instance owns event ${ev?.id ?? '?'} (${ev?.type ?? '?'})`);
303	          return realm.toRealm(who, invoke(who, o.module, o.key, 'event', localise(ev)));
304	        },
305	        ownerOf: ev => realm.toRealm(who, ownerOf(ev)),
306	        emit: (...effects) => { for (const e of effects.flat()) takeEffect(who, ikey, jcopy(e)); return effects.length; },
307	      };
308	    };
309	
310	    // --- a call into a module instance (atomic: on failure nothing it did stays) ---
311	    function invoke(caller, mid, ikey, kind, arg) {
312	      const decl = M.modules[mid];
313	      const rec = [caller, mid, ikey, kind, 'ok'];
314	      trace.calls.push(rec);
315	      if (!decl || !modules[mid]) { rec[4] = 'refused'; throw new InterfaceError('unknown-module', `${mid} is not a declared module`); }
316	      if (typeof ikey !== 'string' || !ikey || ikey.length > 80 || ikey.includes('/')) { rec[4] = 'refused'; throw new InterfaceError('bad-key', `${mid}: the instance key must be a string of 1-80 characters without '/'`); }
317	      if (stack.includes(mid)) { rec[4] = 'refused'; violation('recursion', mid, `${[...stack, mid].join(' -> ')}`); throw new InterfaceError('recursion', `${[...stack, mid].join(' -> ')}`); }
318	      if (stack.length >= MAX_DEPTH) { rec[4] = 'refused'; throw new InterfaceError('depth', `call depth above ${MAX_DEPTH}`); }
319	      const allowed = kind === 'event' && caller === 'parent' ? reach.has(mid) : (declOf(caller).calls ?? []).includes(mid);
320	      if (!allowed) {
321	        violation('call-undeclared', mid, `${caller} -> ${mid} is not in the declared call graph`, { caller });
322	        if (strict) { rec[4] = 'refused'; throw new InterfaceError('call-undeclared', `${caller} -> ${mid} is not in the declared call graph`); }
323	      }
324	      if (kind === 'call') {
325	        const errs = validate(decl.input, arg);
326	        if (errs.length) {
327	          violation('input-schema', mid, errs.join('; '));
328	          if (strict) { rec[4] = 'refused'; throw new InterfaceError('input-schema', `${mid}: ${errs.join('; ')}`); }
329	        }
330	      }
331	      const fn = kind === 'call' ? modules[mid].step : modules[mid].onEvent;
332	      if (typeof fn !== 'function') { rec[4] = 'refused'; throw new InterfaceError('no-entry', `${mid} exports no ${kind === 'call' ? 'step' : 'onEvent'} function`); }
333	      const mark = undo.length;
334	      const rollback = () => { while (undo.length > mark) undo.pop()(); };
335	      const slot = (carry.m[mid] ??= {});
336	      const prev = own(slot, ikey) ? slot[ikey] : null;
337	      const meta = { module: mid, key: ikey, state: prev === null ? null : jcopy(prev), now: input.now };
338	      const ctx = realm.makeCtx(mid, meta, handlersFor(mid, ikey));
339	      stack.push(mid);
340	      let res;
341	      try {
342	        res = fn(realm.toRealm(mid, arg), ctx);
343	        if (res && typeof res.then === 'function') throw new InterfaceError('async', `${mid}: step/onEvent must return a result, not a promise`);
344	        res = res === undefined || res === null ? {} : jcopy(res);
345	        if (!isObj(res)) throw new InterfaceError('bad-result', `${mid}: must return an object`);
346	        if (own(res, 'effects') && !Array.isArray(res.effects)) throw new InterfaceError('bad-result', `${mid}: effects must be an array`);
347	        const oerrs = validate(decl.output, own(res, 'output') ? res.output : null);
348	        if (oerrs.length) {
349	          violation('output-schema', mid, oerrs.join('; '));
350	          if (strict) throw new InterfaceError('output-schema', `${mid}: ${oerrs.join('; ')}`);
351	        }
352	        for (const e of res.effects ?? []) takeEffect(mid, ikey, e);
353	        takeObligations(mid, ikey, res.obligations);
354	        takeTasks(mid, ikey, res.humanTasks);
355	        if (own(res, 'state')) {
356	          const had = own(slot, ikey), old = slot[ikey];
357	          if (res.state === null) delete slot[ikey]; else slot[ikey] = res.state;
358	          undo.push(() => { if (had) slot[ikey] = old; else delete slot[ikey]; });
359	        }
360	      } catch (e) {
361	        rollback();
362	        rec[4] = 'error';
363	        if (!(e instanceof InterfaceError)) violation('module-error', mid, String(e?.message ?? e));
364	        throw e instanceof InterfaceError ? e : new Error(`${mid}: ${String(e?.message ?? e)}`);
365	      } finally { stack.pop(); }
366	      return own(res, 'output') ? res.output : null;
367	    }
368	
369	    // --- the parent ---
370	    const pIn = { kind: input.kind, item: input.item, world: input.world, instance: input.instance, now: input.now, events: input.events, state: carry.p === null ? null : jcopy(carry.p) };
371	    const pctx = realm.makeCtx('parent', { module: 'parent', key: input.instance, state: pIn.state, now: input.now }, handlersFor('parent', input.instance));
372	    let r;
373	    try {
374	      r = parent.tick(realm.toRealm('parent', pIn), pctx);
375	      if (r && typeof r.then === 'function') throw new InterfaceError('async', 'parent.tick must return a result, not a promise');
376	      r = jcopy(r);
377	      if (!isObj(r)) throw new InterfaceError('bad-result', 'parent.tick must return an object');
378	    } catch (e) {
379	      const brief = { violations: trace.violations.slice(0, 5), calls: trace.calls.length };
380	      const err = new Error(`${String(e?.message ?? e).slice(0, 1500)} [composition ${JSON.stringify(brief).slice(0, 400)}]`);
381	      err.composition = trace;
382	      throw err;
383	    }
384	    for (const e of r.effects ?? []) takeEffect('parent', input.instance, e);
385	    takeObligations('parent', input.instance, r.obligations);
386	    takeTasks('parent', input.instance, r.humanTasks);
387	    if (own(r, 'state')) carry.p = r.state ?? null;
388	    const decisions = isObj(r.decisions) ? { ...r.decisions, composition: trace } : r.decisions;
389	    const output = { decisions, effects: out.effects, obligations: { upsert: out.upsert, cancel: out.cancel }, humanTasks: out.tasks, carry };
390	    if (own(r, 'merge')) output.merge = r.merge;
391	    if (own(r, 'close')) output.close = r.close;
392	    return output;
393	  }
394	  return { id, tick, mode, runtime: RUNTIME_VERSION };
395	}
396	
397	// ---------------------------------------------------------------------------------------------------------------------
398	// E8 effect kinds (the item's qualifier): 'system.op', plus the target of a status change and its status, and the
399	// template of a notification. A declaration covers an effect when it names any of its kinds.
400	
401	export function kindsOfE8(e) {
402	  const base = `${e?.system}.${e?.op}`;
403	  const out = [base];
404	  if (base === 'orders.setStatus') {
405	    const target = e.args?.fulfilmentId === null || e.args?.fulfilmentId === undefined ? 'order' : 'fulfilment';
406	    out.push(`${base}:${target}`, `${base}:${target}:${e.args?.status}`);
407	  }
408	  if (base === 'notify.send') out.push(`${base}:${e.args?.template}`);
409	  return out;
410	}
