// fulfil: one fulfilment's saga (R4.2 reserve, charge, ship), its carrier messages (R4.4), and its compensation (R5.1).
// Keys: 'reserve' (items 'r0', 'r1', ...), 'charge', 'ship', 'status-<to>', 'notice', and the undo keys 'release-<item>',
// 'refund', 'ship-cancel'. The parent calls op 'start' when the order is ready, 'carrier' for each report about this
// fulfilment, and 'compensate' (with reason 'cancelled' or 'failed') when the order is cancelled.

const isObj = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const resultOf = p => {
  for (const k of ['result', 'data', 'value', 'output']) if (isObj(p?.[k])) return p[k];
  return isObj(p) ? p : {};
};
const FAIL_CODES_INVALID = ['invalid-args', 'field-renamed'];

const setStatus = (st, status, key) => ({ key, system: 'orders', op: 'setStatus', args: { orderId: st.orderId, fulfilmentId: st.fid, status } });

// Compensation (R5.1): cancel the shipment (not if collection failed), refund the charge, release each committed item.
// Only steps that committed and are not undone yet are undone (never twice, never a step that did not commit).
function undoSteps(st) {
  const effects = [];
  const undone = { ...st.undone };
  if (st.ship === 'ok' && !undone.ship && st.carrier !== 'collectionFailed') {
    effects.push({ key: 'ship-cancel', system: 'carrier', op: 'cancel', args: { orderId: st.orderId, fulfilmentId: st.fid }, compensates: 'ship' });
    undone.ship = true;
  }
  if (st.charge === 'ok' && !undone.refund) {
    effects.push({ key: 'refund', system: 'billing', op: 'refund', args: { orderId: st.orderId, fulfilmentId: st.fid, amountMinor: st.amountMinor }, compensates: 'charge' });
    undone.refund = true;
  }
  for (const it of st.items) {
    if (st.res[it.key] === 'ok' && !undone[it.key]) {
      effects.push({ key: `release-${it.key}`, system: 'inventory', op: 'release', args: { orderId: st.orderId, fulfilmentId: st.fid, sku: it.sku }, compensates: it.key });
      undone[it.key] = true;
    }
  }
  return { effects, undone };
}

const reserveEffect = st => ({
  key: 'reserve', system: 'inventory', op: 'reserve',
  args: { orderId: st.orderId, fulfilmentId: st.fid, location: st.location,
    items: st.items.filter(it => st.res[it.key] !== 'ok').map(it => ({ key: it.key, sku: it.sku, qty: it.qty })) },
});

// Advance after a step committed: reserve -> charge -> ship.
function advance(st) {
  if (st.phase !== 'reserving') return null;
  if (st.items.every(it => st.res[it.key] === 'ok')) {
    return { state: { ...st, phase: 'charging' }, effects: [{ key: 'charge', system: 'billing', op: 'charge', args: { orderId: st.orderId, fulfilmentId: st.fid, customerId: st.customerId, amountMinor: st.amountMinor, currency: st.currency } }] };
  }
  return null;
}

export function step(input, ctx) {
  if (input.op !== 'start') return { output: { phase: ctx.state?.phase ?? 'none' } };
  if (ctx.state) return { output: { phase: ctx.state.phase } };
  const items = input.items.map((it, i) => ({ key: `r${i}`, sku: it.sku, qty: it.qty }));
  const st = { orderId: input.orderId, fid: input.fid, location: input.location, customerId: input.customerId,
    currency: input.currency, amountMinor: input.amountMinor, items, res: {}, charge: 'none', ship: 'none', shipRef: null,
    carrier: null, phase: 'reserving', undone: {} };
  return { state: st, effects: [setStatus(st, 'processing', 'status-processing'), reserveEffect(st)], output: { phase: 'reserving' } };
}

export function onEvent(event, ctx) {
  const st = ctx.state;
  if (!st) return { output: { phase: 'none' } };
  if (event?.type === 'effect.result') return onResult(event.payload ?? {}, st, ctx);
  return { output: { phase: st.phase } };
}

function onResult(p, st, ctx) {
