  if (s !== 'ok') return { output: { phase: st.phase } };
  const next = { ...st, ship: 'ok' };
  if (st.phase !== 'shipping') {
    const u = undoSteps(next);
    return { state: { ...next, undone: u.undone }, effects: u.effects, output: { phase: st.phase, lateUndo: true } };
  }
