      if (items) for (const it of items) if (it?.status === 'ok') next.res[it.key] = 'ok';
      if (p.status === 'ok') for (const it of st.items) next.res[it.key] = 'ok';
    }
    if (p.status === 'error' && FAIL_CODES_INVALID.includes(p.error?.code)) {
      return { state: next, effects: [reserveEffect(next)], output: { phase: 'reserving', retried: true } };     // our request was wrong: re-issue
    }
    if (p.status === 'error' || (items && items.some(it => it?.status === 'error' && it.error?.retryable === false))) {
      return fail(next, ctx, 'reserve');
    }
    if (st.phase !== 'reserving') {
      // a step that committed after the fulfilment was cancelled or failed is compensated at once (S14, R6.2)
      const u = undoSteps(next);
