// fulfil: one fulfilment's saga (R4.2 reserve, charge, ship), its carrier messages (R4.4), and its compensation (R5.1).
// Keys: 'reserve' (items 'r0', 'r1', ...), 'charge', 'ship', 'status-<to>', 'notice', and the undo keys 'release-<item>',
// 'refund', 'ship-cancel'. The parent calls op 'start' when the order is ready, 'carrier' for each report about this
// fulfilment, and 'compensate' (with reason 'cancelled' or 'failed') when the order is cancelled.

const isObj = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const resultOf = p => {
  for (const k of ['result', 'data', 'value', 'output']) if (isObj(p?.[k])) return p[k];
  return isObj(p) ? p : {};
};
const FAIL_CODES_INVALID = ['invalid-args', 'field-renamed'];

const setStatus = (st, status, key) => ({ key, system: 'orders', op: 'setStatus', args: { orderId: st.orderId, fulfilmentId: st.fid, status } });

// Compensation (R5.1): cancel the shipment (not if collection failed), refund the charge, release each committed item.
// Only steps that committed and are not undone yet are undone (never twice, never a step that did not commit).
function undoSteps(st) {
  const effects = [];
  const undone = { ...st.undone };
  if (st.ship === 'ok' && !undone.ship && st.carrier !== 'collectionFailed') {
    effects.push({ key: 'ship-cancel', system: 'carrier', op: 'cancel', args: { orderId: st.orderId, fulfilmentId: st.fid }, compensates: 'ship' });
    undone.ship = true;
  }
  if (st.charge === 'ok' && !undone.refund) {
    effects.push({ key: 'refund', system: 'billing', op: 'refund', args: { orderId: st.orderId, fulfilmentId: st.fid, amountMinor: st.amountMinor }, compensates: 'charge' });
    undone.refund = true;
  }
  for (const it of st.items) {
    if (st.res[it.key] === 'ok' && !undone[it.key]) {
      effects.push({ key: `release-${it.key}`, system: 'inventory', op: 'release', args: { orderId: st.orderId, fulfilmentId: st.fid, sku: it.sku }, compensates: it.key });
      undone[it.key] = true;
    }
  }
  return { effects, undone };
}

// A batch op keys its items, not the batch: each item's key ('r0', 'r1', ...) is what its result is routed by.
const reserveEffect = st => ({
  system: 'inventory', op: 'reserve',
  args: { orderId: st.orderId, fulfilmentId: st.fid, location: st.location,
    items: st.items.filter(it => st.res[it.key] !== 'ok').map(it => ({ key: it.key, sku: it.sku, qty: it.qty })) },
});

// Advance after a step committed: reserve -> charge -> ship.
function advance(st) {
  if (st.phase !== 'reserving') return null;
  if (st.items.every(it => st.res[it.key] === 'ok')) {
    return { state: { ...st, phase: 'charging' }, effects: [{ key: 'charge', system: 'billing', op: 'charge', args: { orderId: st.orderId, fulfilmentId: st.fid, customerId: st.customerId, amountMinor: st.amountMinor, currency: st.currency } }] };
  }
  return null;
}

export function step(input, ctx) {
  const st = ctx.state;
  if (input.op === 'start') {
    if (st) return { output: { phase: st.phase } };
    const items = input.items.map((it, i) => ({ key: `r${i}`, sku: it.sku, qty: it.qty }));
    const next = { orderId: input.orderId, fid: input.fid, location: input.location, customerId: input.customerId, email: input.email,
      currency: input.currency, amountMinor: input.amountMinor, items, res: {}, charge: 'none', ship: 'none', carrier: null,
      phase: 'reserving', undone: {}, attempts: 0 };
    return { state: next, effects: [setStatus(next, 'processing', 'status-processing'), reserveEffect(next)], output: { phase: 'reserving' } };
  }
  if (!st) return { output: { phase: 'none' } };
  if (input.op === 'carrier') return carrier(input.meaning, input.reportedAt, st, ctx);
  if (input.op === 'compensate') return cancelFulfilment(st, input.reason);
  return { output: { phase: st.phase } };
}

// R4.4: a carrier report about this fulfilment. Reports about a finished or cancelled fulfilment change nothing.
function carrier(meaning, reportedAt, st, ctx) {
  const open = ['reserving', 'charging', 'charged', 'shipping', 'shipped', 'dispatched'].includes(st.phase);
  if (!open || st.ship !== 'ok') return { output: { phase: st.phase, changed: false } };
  if (meaning === 'collected') {
    if (st.phase !== 'shipped') return { output: { phase: st.phase, changed: false } };
    return { state: { ...st, phase: 'dispatched', collected: reportedAt }, effects: [setStatus(st, 'dispatched', 'status-dispatched')], output: { phase: 'dispatched', collected: true } };
  }
  if (meaning === 'delivered') {
    const effects = st.phase === 'dispatched' ? [] : [setStatus(st, 'dispatched', 'status-dispatched')];
    effects.push(setStatus(st, 'completed', 'status-completed'));
    return { state: { ...st, phase: 'completed' }, effects, output: { phase: 'completed', collected: true } };
  }
  if (meaning === 'collectionFailed') {
    return fail({ ...st, carrier: 'collectionFailed' }, ctx, 'carrier', 'collection-failed');
  }
  return { output: { phase: st.phase, changed: false } };       // inTransit, info
}

// R6.1 / R6.2: the order is cancelled; this fulfilment is compensated and set cancelled.
function cancelFulfilment(st, reason) {
  if (['completed', 'failed', 'cancelled'].includes(st.phase)) return { output: { phase: st.phase, changed: false } };
  const next = { ...st, phase: 'cancelled' };
  const u = undoSteps(next);
  return { state: { ...next, undone: u.undone }, effects: [...u.effects, setStatus(next, 'cancelled', 'status-cancelled')], output: { phase: 'cancelled', reason } };
}

export function onEvent(event, ctx) {
  const st = ctx.state;
  if (!st) return { output: { phase: 'none' } };
  if (event?.type === 'effect.result') return onResult(event.payload ?? {}, st, ctx);
  return { output: { phase: st.phase } };
}

function onResult(p, st, ctx) {
  // a batch result comes back with its items (keyed r0, r1, ...) and no batch key of its own
  const rs = Array.isArray(p.items) || p.key === 'reserve' ? 'reserve' : p.key === 'charge' ? 'charge' : p.key === 'ship' ? 'ship' : null;
  if (!rs) return { output: { phase: st.phase } };
  const final = (x) => {
    // unknown: the committed truth is status(key) (S2)
    if (x.status === 'unknown') return ctx.status(rs === 'reserve' ? 'inventory' : rs === 'charge' ? 'billing' : 'carrier', p.key) === 'committed' ? 'ok' : 'error';
    return x.status;
  };
  if (rs === 'reserve') {
    // per-item outcomes: committed items stay, failed ones are resubmitted with their original keys (R4.2)
    const items = Array.isArray(p.items) ? p.items : null;
    const next = { ...st, res: { ...st.res } };
    if (p.status === 'ok' || p.status === 'partial') {
      if (items) for (const it of items) if (it?.status === 'ok') next.res[it.key] = 'ok';
      if (p.status === 'ok') for (const it of st.items) next.res[it.key] = 'ok';
    }
    if (p.status === 'error' && FAIL_CODES_INVALID.includes(p.error?.code)) {
      return { state: next, effects: [reserveEffect(next)], output: { phase: 'reserving', retried: true } };     // our request was wrong: re-issue
    }
    if (p.status === 'error' || (items && items.some(it => it?.status === 'error' && it.error?.retryable === false))) {
      return fail(next, ctx, 'reserve');
    }
    if (st.phase !== 'reserving') {
      // a step that committed after the fulfilment was cancelled or failed is compensated at once (S14, R6.2)
      const u = undoSteps(next);
      return { state: { ...next, undone: u.undone }, effects: u.effects, output: { phase: st.phase, lateUndo: true } };
    }
    const flagged = next.items.filter(it => next.res[it.key] !== 'ok');
    if (flagged.length && next.attempts < 5) {
      // a partial batch: resubmit only the failed items, same keys, inside the window (R4.2)
      const again = { ...next, attempts: next.attempts + 1 };
      return { state: again, effects: [reserveEffect(again)], output: { phase: 'reserving', resubmitted: flagged.length } };
    }
    if (flagged.length) return fail(next, ctx, 'reserve', 'reserve-exhausted');
    const a = advance(next);
    return a ? { ...a, output: { phase: 'charging' } } : { state: next, output: { phase: 'reserving' } };
  }
  if (rs === 'charge') {
    const s = final(p);
    if (p.error?.code === 'card-declined' || (s === 'error' && p.error?.retryable === false)) {
      return fail({ ...st, charge: 'declined' }, ctx, 'charge', p.error?.code === 'card-declined' ? 'card-declined' : null);
    }
    if (s !== 'ok') return { output: { phase: st.phase } };
    const next = { ...st, charge: 'ok' };
    if (st.phase !== 'charging') {
      const u = undoSteps(next);                                                          // committed after cancel/failure
      return { state: { ...next, undone: u.undone }, effects: u.effects, output: { phase: st.phase, lateUndo: true } };
    }
    const ship = { key: 'ship', system: 'carrier', op: 'create', args: { orderId: st.orderId, fulfilmentId: st.fid, location: st.location, ref: st.fid } };
    return { state: { ...next, phase: 'shipping', shipRef: st.fid }, effects: [ship], output: { phase: 'shipping' } };
  }
  // ship
  const s = final(p);
  if (p.error?.retryable === false && !FAIL_CODES_INVALID.includes(p.error?.code)) return fail({ ...st, ship: 'error' }, ctx, 'ship');
  if (FAIL_CODES_INVALID.includes(p.error?.code)) return { state: st, effects: [{ key: 'ship', system: 'carrier', op: 'create', args: { orderId: st.orderId, fulfilmentId: st.fid, location: st.location, ref: st.fid } }], output: { phase: 'shipping', retried: true } };
  if (s !== 'ok') return { output: { phase: st.phase } };
  const next = { ...st, ship: 'ok' };
  if (st.phase !== 'shipping') {
    const u = undoSteps(next);
    return { state: { ...next, undone: u.undone }, effects: u.effects, output: { phase: st.phase, lateUndo: true } };
  }
  return { state: { ...next, phase: 'shipped' }, output: { phase: 'shipped' } };
}

// R5.2: the fulfilment fails: compensate what committed, set failed, tell the customer.
function fail(st, ctx, where, why = null) {
  const u = undoSteps(st);
  const effects = [...u.effects, setStatus(st, 'failed', 'status-failed')];
  effects.push({ key: 'notice', system: 'notify', op: 'send', args: { to: st.email ?? '', about: st.fid, template: 'fulfilment-failed', text: `Fulfilment ${st.fid} failed (${why ?? where}).` } });
  return { state: { ...st, phase: 'failed', undone: u.undone }, effects, output: { phase: 'failed', where, why } };
}

